def build(slug, c):
    s = T
    s = re.sub(r'<title>.*?</title>', '<title>%s</title>' % c['title'], s, flags=re.S)
    s = re.sub(r'<meta name="description" content="[^"]*">', '<meta name="description" content="%s">' % c['desc'], s)
    s = re.sub(r'<link rel="canonical" href="[^"]*">', '<link rel="canonical" href="https://санаториикмв.рф/%s">' % (slug + '/' if slug else ''), s)
    s = re.sub(r'<meta property="og:title" content="[^"]*">', '<meta property="og:title" content="%s">' % c['h1'], s)
    s = re.sub(r'<body[^>]*>', '<body data-g="%s">' % c['g'], s, count=1)
    s = re.sub(r'(<p class="kicker" id="heroKicker">)[^<]*', r'\g<1>' + c['kicker'], s)
    s = re.sub(r'(<h1 id="heroTitle">)[^<]*', r'\g<1>' + c['h1'], s)
    s = re.sub(r'(<p class="lead" id="heroLead">)[^<]*', r'\g<1>' + c['lead'], s)
    s = s.replace('<div class="hero-art" aria-hidden="true">', '<div class="hero-art" aria-hidden="true" style="--hd:url(/img/%s.jpg);--hm:url(/img/%s.jpg)">' % (c['hd'], c['hm']))
    if c['resort']:
        s = s.replace('<input type="radio" name="resort" value="%s">' % c['resort'], '<input type="radio" name="resort" value="%s" checked>' % c['resort'])
    # курорт страницы — первым и выделен
    m = re.search(r'(<div class="resorts">\s*)(.*?)(\s*</div>\s*<p class="fine">)', s, flags=re.S)
    arts = re.findall(r'<article class="resort".*?</article>', m.group(2), flags=re.S)
    if c['first']:
        arts.sort(key=lambda a: 0 if '<h3>%s</h3>' % c['first'] in a else 1)
        arts[0] = arts[0].replace('<article class="resort"', '<article class="resort is-match"', 1)
    s = s[:m.start(2)] + '\n      '.join(arts) + s[m.end(2):]
    # цены
    cards = []
    for i, (city, name, rub, note, d14) in enumerate(c['prices']):
        img = ['price-standard', 'price-comfort', 'price-premium'][i]
        cards.append('<div class="price%s"><img src="/img/%s.jpg" alt="" loading="lazy" width="1200" height="800"><span class="p-cls">%s</span><h3>%s</h3><b>от %s ₽</b><span>сутки на человека с лечением и питанием</span><em>14 дней — от %s ₽</em></div>' % (' hl' if i == 1 else '', img, city, name, rub, d14))
    s = re.sub(r'<div class="price-grid">.*?</div>\s*</div>\s*<p class="fine">', '<div class="price-grid">\n      ' + '\n      '.join(cards) + '\n    </div>\n    <p class="fine">', s, count=1, flags=re.S)
    s = re.sub(r'(<section id="prices"[^>]*>\s*<div class="wrap">\s*<div class="sec-head"><h2>)[^<]*', r'\g<1>' + c['ph'], s)
    s = re.sub(r'\?v=\d+', '?v=' + V, s)
    path = (slug + '/' if slug else '') + 'index.html'
    if slug: os.makedirs(slug, exist_ok=True)
    open(path, 'w', encoding='utf-8').write(s)
    return path
for slug, c in P.items(): print(build(slug, c))
sm = ''.join('<url><loc>https://xn--80aagxamodkugp.xn--p1ai/%s</loc></url>' % (k + '/' if k else '') for k in P)
open('sitemap.xml', 'w').write('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">%s</urlset>\n' % sm)
